#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-17

# Test: stale-cache-cleanup actually reclaims, and never deletes a version a
# live process is running from. (#3483)
#
# Runs the SHIPPED bundle via run-hook.mjs against a fixture HOME, not the TS
# source, because the defect this covers was a constant that a source-level unit
# test with its own fixture would happily have mirrored.
#
# Two invariants, and the second is the one with teeth:
#
#   1. RECLAIM. The hook must prune old versions under the channel that is
#      actually installed. It used to hardcode .../cache/orchestkit/ork while
#      every real install is orchestkit/ork-alpha, so readdirSync threw, the
#      bare catch swallowed it, and the hook returned success having done
#      nothing. A silent no-op is indistinguishable from a clean run.
#
#   2. LIVENESS. `.in_use` is NOT a boolean marker. It is a directory of
#      `<pid>` files each holding {"pid":N,"procStart":"..."}. Measured on a
#      real machine: 39 entries, 11 live and 28 stale. So "keep the 2 newest"
#      is not a safe policy on its own; a session running an older version
#      would have its plugin deleted underneath it. A version held by a LIVE
#      pid must survive regardless of age.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
RUNNER="$REPO_ROOT/src/hooks/bin/run-hook.mjs"

FAILED=0
FIX=""
cleanup() { [ -n "$FIX" ] && [ -d "$FIX" ] && rm -rf "$FIX"; FIX=""; }
trap cleanup EXIT

echo "=== Stale Cache Cleanup Test (#3483) ==="
echo ""

if [ ! -f "$RUNNER" ]; then
    echo "FAIL: hook runner not found at $RUNNER"
    exit 1
fi

# A pid that is certainly not running. 2^22 is above the macOS/Linux default
# pid_max, so it can never be allocated.
DEAD_PID=4194303
LIVE_PID=$$

# Sets FIX and CH as globals. Must NOT be called via $( ), which would run it
# in a subshell and leave FIX empty in the parent; an empty HOME then resolves
# to /.claude/... and the hook silently no-ops, which reads exactly like the
# bug under test. That mistake cost a debugging cycle here, so it is spelled out.
make_fixture() {
    FIX="$(mktemp -d)"
    local ch="$FIX/.claude/plugins/cache/orchestkit/$1"; shift
    mkdir -p "$ch"
    for spec in "$@"; do
        local ver="${spec%%:*}" hold="${spec##*:}"
        mkdir -p "$ch/$ver/.in_use"
        printf 'payload\n' > "$ch/$ver/marker.txt"
        case "$hold" in
            live) printf '{"pid":%s,"procStart":"x"}\n' "$LIVE_PID" > "$ch/$ver/.in_use/$LIVE_PID" ;;
            stale) printf '{"pid":%s,"procStart":"x"}\n' "$DEAD_PID" > "$ch/$ver/.in_use/$DEAD_PID" ;;
            none) : ;;
        esac
    done
    CH="$ch"
}

# The runner's exit code is part of the contract: a crashed hook must fail the
# test rather than be read as "nothing needed cleaning".
run_hook() {
    local out rc
    if [ -z "$FIX" ] || [ ! -d "$FIX" ]; then
        echo "  FAIL: fixture HOME is unset or missing; refusing to run against the real \$HOME"
        FAILED=1
        return
    fi
    set +e
    out="$(printf '{"session_id":"00000000-0000-4000-8000-000000000000","hook_event_name":"SessionStart"}' \
          | HOME="$FIX" node "$RUNNER" lifecycle/stale-cache-cleanup 2>&1)"
    rc=$?
    set -e
    if [ "$rc" -ne 0 ]; then
        echo "  FAIL: hook runner exited $rc"
        printf '%s\n' "$out" | sed 's/^/        /' | head -5
        FAILED=1
    fi
}

present() { [ -d "$1/$2" ] && echo yes || echo no; }

check() {
    local label="$1" want="$2" got="$3"
    if [ "$want" = "$got" ]; then
        echo "  PASS: $label (present=$got)"
    else
        echo "  FAIL: $label expected present=$want, got present=$got"
        FAILED=1
    fi
}

# ---- 1. reclaims under the channel that is actually installed --------------
echo "--- 1: prunes old versions under the installed channel (ork-alpha) ---"
make_fixture ork-alpha 1.0.0:stale 1.0.1:stale 1.0.2:stale 1.0.3:stale
run_hook
check "1.0.0 (oldest, stale) pruned" no  "$(present "$CH" 1.0.0)"
check "1.0.1 (stale) pruned"         no  "$(present "$CH" 1.0.1)"
check "1.0.2 (recent) kept"          yes "$(present "$CH" 1.0.2)"
check "1.0.3 (newest) kept"          yes "$(present "$CH" 1.0.3)"
cleanup; echo ""

# ---- 2. never deletes a version a LIVE pid is running from -----------------
echo "--- 2: a live holder survives regardless of age ---"
make_fixture ork-alpha 1.0.0:live 1.0.1:stale 1.0.2:stale 1.0.3:stale
run_hook
check "1.0.0 (oldest but LIVE) kept" yes "$(present "$CH" 1.0.0)"
check "1.0.1 (stale) pruned"         no  "$(present "$CH" 1.0.1)"
check "1.0.3 (newest) kept"          yes "$(present "$CH" 1.0.3)"
cleanup; echo ""

# ---- 3. the stable channel is handled too, not just the alpha one ----------
echo "--- 3: works for the stable channel as well ---"
make_fixture ork 8.0.0:stale 8.0.1:stale 8.0.2:stale 8.0.3:stale
run_hook
check "8.0.0 pruned"      no  "$(present "$CH" 8.0.0)"
check "8.0.3 kept"        yes "$(present "$CH" 8.0.3)"
cleanup; echo ""

echo "=== Summary ==="
if [ "$FAILED" -ne 0 ]; then
    echo "RESULT: FAIL"
    exit 1
fi
echo "RESULT: PASS"
exit 0
